INSERT INTO facets (`slug`, `page_type`, `parent_slug`, `h1`, `title`, `intro_copy`, `meta_title`, `meta_description`, `rules`, `canonical_path`, `indexable`, `position`) VALUES
  ('toyota', 'make', NULL, 'Toyota cars for sale in Port Harcourt', 'Toyota for sale in Port Harcourt', 'Toyota is the default PH buy for a reason: parts on every street, mechanics who know the platform, and resale value that holds. Every car here is graded honestly — you can see which ones our inspectors have physically checked.', 'Toyota Cars for Sale in Port Harcourt | HonestCars', 'Browse verified Toyota cars for sale in Port Harcourt — Camry, Corolla, RAV4, Highlander, Hilux. Honest prices, inspection grades, no dealer games.', '{"make":"Toyota"}', '/cars/toyota', 1, 10),
  ('toyota/camry', 'model', 'toyota', 'Toyota Camry for sale in Port Harcourt', 'Toyota Camry in Port Harcourt', 'The Camry is the safest first buy in Port Harcourt: comfortable, cheap to service, and easy to resell. Below is live Camry stock with mileage, documents status and our verification grade on each one.', 'Toyota Camry for Sale in Port Harcourt | HonestCars', 'Live Toyota Camry listings in Port Harcourt with honest prices, verified mileage and inspection grades. Compare 2010–2018 Camry stock before you travel.', '{"make":"Toyota","model":"Camry"}', '/cars/toyota/camry', 1, 11),
  ('toyota/corolla', 'model', 'toyota', 'Toyota Corolla for sale in Port Harcourt', 'Toyota Corolla in Port Harcourt', 'Corolla money is safe money in PH. Fuel is light, parts are cheap, and a well-kept example will not embarrass you. We list the mileage as it is — verified where an inspector has seen the odometer.', 'Toyota Corolla for Sale in Port Harcourt | HonestCars', 'Toyota Corolla listings in Port Harcourt with verified mileage, document status and honest condition notes. Prices from the live PH market.', '{"make":"Toyota","model":"Corolla"}', '/cars/toyota/corolla', 1, 12),
  ('honda', 'make', NULL, 'Honda cars for sale in Port Harcourt', 'Honda for sale in Port Harcourt', 'Hondas hold their value in Port Harcourt and the Accord and CR-V are the two we see most. Check the grade on each listing — Certified means we scanned it ourselves and wrote down what we found.', 'Honda Cars for Sale in Port Harcourt | HonestCars', 'Browse Honda cars for sale in Port Harcourt — Accord, CR-V, Civic, Pilot. Verified grades, real mileage, honest condition notes.', '{"make":"Honda"}', '/cars/honda', 1, 20),
  ('honda/accord', 'model', 'honda', 'Honda Accord for sale in Port Harcourt', 'Honda Accord in Port Harcourt', 'The Accord gives you Camry comfort with a bit more presence. Service costs are close, parts are available around Ikwerre Road and Rumuokoro. Ask us for the history on any car below.', 'Honda Accord for Sale in Port Harcourt | HonestCars', 'Honda Accord listings in Port Harcourt with honest prices, mileage and verification grades. Compare before you call.', '{"make":"Honda","model":"Accord"}', '/cars/honda/accord', 1, 21),
  ('lexus', 'make', NULL, 'Lexus cars for sale in Port Harcourt', 'Lexus for sale in Port Harcourt', 'Lexus money buys you Toyota reliability with a quieter cabin. Fuel and suspension parts cost more than a Camry, so we flag anything the inspector found before you commit.', 'Lexus Cars for Sale in Port Harcourt | HonestCars', 'Verified Lexus listings in Port Harcourt — RX 350, ES 350, GX 460. Real prices, inspection grades and document status on every car.', '{"make":"Lexus"}', '/cars/lexus', 1, 30),
  ('suv-under-15m', 'body_budget', NULL, 'SUVs under ₦15m in Port Harcourt', 'SUVs under ₦15m in Port Harcourt', 'Family height and Abuja-road confidence do not have to start at ₦20m. Everything here is under ₦15,000,000 and every price is the price — what you see is what the dealer is asking.', 'SUVs Under ₦15m in Port Harcourt | HonestCars', 'SUVs under ₦15 million in Port Harcourt — RAV4, CR-V, Sportage, X-Trail and more, with mileage, documents and verification grades.', '{"body_type":"suv","max_price_kobo":1500000000}', '/cars/suv-under-15m', 1, 40),
  ('suv-under-25m', 'body_budget', NULL, 'SUVs under ₦25m in Port Harcourt', 'SUVs under ₦25m in Port Harcourt', 'This is the sweet spot for a PH family: newer RAV4, Highlander and Santa Fe money. Compare the certified ones first — the inspection report tells you what the photos will not.', 'SUVs Under ₦25m in Port Harcourt | HonestCars', 'SUVs under ₦25 million in Port Harcourt with verified mileage, inspection grades and honest condition notes.', '{"body_type":"suv","max_price_kobo":2500000000}', '/cars/suv-under-25m', 1, 41),
  ('sedan-under-10m', 'body_budget', NULL, 'Sedans under ₦10m in Port Harcourt', 'Sedans under ₦10m in Port Harcourt', 'Clean, sensible saloon cars under ₦10m — mostly Camry, Corolla, Elantra and Altima. Good for a first car, better for a daily commute through Rumuokoro.', 'Sedans Under ₦10m in Port Harcourt | HonestCars', 'Sedans under ₦10 million in Port Harcourt — Camry, Corolla, Elantra, Altima. Honest prices, grades and mileage.', '{"body_type":"sedan","max_price_kobo":1000000000}', '/cars/sedan-under-10m', 1, 42),
  ('certified', 'tag', NULL, 'HonestCars-Certified cars in Port Harcourt', 'HonestCars-Certified cars in Port Harcourt', 'These are the cars our inspectors have scanned, driven and photographed themselves — with an honest condition note on each listing that names the faults instead of hiding them.', 'HonestCars-Certified Cars in Port Harcourt | HonestCars', 'Every HonestCars-Certified car in Port Harcourt: OBD2 scan, documents sighted, road test, honest condition note. Browse the fully inspected stock.', '{"grade":"certified"}', '/cars/certified', 1, 50);
INSERT INTO services (`slug`, `name`, `promise`, `icon`, `from_price_kobo`, `cta_label`, `position`, `is_active`, `hero_copy`, `deliverables`, `included`, `excluded`, `steps`, `pricing`, `proof`, `jobs_done`, `booking_kind`, `sla_copy`) VALUES
  ('inspection', 'Pre-Purchase Inspection', 'An inspector stands next to the car, scans it and tells you the truth before you pay.', 'search-check', 2500000, 'Book inspection', 10, 1, 'An inspector stands next to the car, scans it, checks the papers and writes down what is actually wrong with it. You get the report before you spend a naira — including the parts the seller would rather you did not know about.', '[{"title":"OBD2 scan","copy":"Every fault code read and photographed, including the stored history the dash light hides."},{"title":"Panel & chassis check","copy":"Paint depth, panel gaps, jig marks and the spare-wheel well — the three places flood and accident repairs hide."},{"title":"Documents sighted","copy":"Customs papers, registration and duty documents read by us, not described to us by a seller."},{"title":"Road test","copy":"Gearbox, suspension, brakes and steering driven on real Port Harcourt roads — not around the lot."},{"title":"Photo record","copy":"Front ¾, rear ¾, interior, dash, engine bay and odometer, so you can compare two cars properly."},{"title":"Honest note, in writing","copy":"A plain-language paragraph naming the faults. It goes on the listing where the buyer can read it."}]', '["Physical inspection at the seller’s location in Port Harcourt","OBD2 scan with photographed codes","Document verification (customs, registration, duty)","Road test on public roads","Photo set and written honesty note","Report delivered within 4 hours of the check"]', '["Repairs of any kind — we inspect, we do not fix","Government agency fees for document transfer","Cars outside Rivers State (arrangeable, travel quoted separately)","Lifting the car on a ramp — we can arrange it at extra cost if you want it"]', '[{"title":"Book and pay for the slot","copy":"Pick a date, tell us where the car is, pay the inspection fee.","timeline":"2 minutes"},{"title":"We confirm with the seller","copy":"We call the dealer and lock the appointment so the car is clean and ready.","timeline":"Within 2 hours"},{"title":"The inspector attends","copy":"You do not need to be there. You get a call 30 minutes before arrival if you want to be.","timeline":"On your chosen date"},{"title":"Report delivered","copy":"Photos, codes, documents status and the honest note land in your account and on WhatsApp.","timeline":"Within 4 hours of the check"},{"title":"You decide","copy":"Buy, negotiate with our report in hand, or walk away. We do not get paid by the seller, so we have no reason to sell you the car.","timeline":"Your call"}]', '[{"tier":"Single car","price":"from ₦25,000","includes":["One inspection, one car","Full report in 4 hours","WhatsApp follow-up with the inspector"],"price_kobo":2500000},{"tier":"Two cars compared","price":"from ₦45,000","includes":["Two inspections","Side-by-side comparison page","A recommendation you can act on"],"price_kobo":4500000},{"tier":"Certified listing pack","price":"from ₦40,000","includes":["Inspection + report","HonestCars-Certified grade on the listing","Better price positioning for sellers"],"price_kobo":4000000}]', '[{"name":"Chidi O.","area":"Woji","quote":"They told me the Camry I liked had a resprayed boot lid before I paid. No other lot would have said that. I bought it anyway, with my eyes open."},{"name":"Tunde A.","area":"Trans-Amadi","quote":"The report had photos of the actual fault codes. My mechanic read it and agreed with every line."}]', 612, 'inspection', 'Report lands in your account within 4 hours of the check.'),
  ('concierge', 'Find-My-Car Concierge', 'Tell us the brief once. We bring up to 3 verified, inspected options in 48–72 hours.', 'compass', 5000000, 'Start my search', 20, 1, 'Tell us the brief once — budget, use, must-haves — and we search the network, inspect the shortlist and bring you up to three verified options within 48–72 hours. You never speak to a dealer you have not chosen.', '[{"title":"A real search, not a filter","copy":"We call partner lots, check stock we have not listed, and look at cars that match your brief rather than your keywords."},{"title":"Every option inspected","copy":"Physical inspection of each car we put in front of you, with the report attached. This is included, not an upsell."},{"title":"Documents checked","copy":"Customs, registration and duty status confirmed before the car makes your shortlist."},{"title":"A shortlist, not a dump","copy":"Up to three options with the honest case for and against each one. Fewer options is the point."},{"title":"Negotiation on your behalf","copy":"We know the market band for the model and we negotiate from it, with the inspection report on the table."},{"title":"Protected purchase","copy":"If you buy through us, payment moves through HonestCars-protected channels and milestones, not directly to a seller."}]', '["Up to 3 inspected, document-checked options inside 48–72 hours","An options page you can open on your phone, with photos and reports","Viewings arranged and attended with you","Negotiation against live market data","Retainer credited against the success fee when you buy through us"]', '["The car itself — you pay the seller, through us","Financing (we can introduce a partner, we do not lend)","Cars outside Rivers State unless you ask for them","The success fee, which is separate and always quoted before you commit"]', '[{"title":"Send the brief","copy":"Four short steps: the car you want, the protection you want, who you are, and the retainer.","timeline":"10 minutes"},{"title":"We search and inspect","copy":"Network calls, physical inspections, document checks — the work you would otherwise do for three weekends.","timeline":"48–72 hours"},{"title":"Options ready","copy":"Up to three cars on a comparison page, with the honest case for each. You pick which to see.","timeline":"Day 3"},{"title":"Viewings","copy":"We attend with you, or go alone and send video. Your call.","timeline":"Your schedule"},{"title":"Close, protected","copy":"We negotiate, you pay through protected channels, and the documents are completed before handover.","timeline":"Same week"}]', '[{"tier":"Concierge search","price":"₦50,000 retainer","includes":["Credited against the success fee","Refunded if we find nothing that meets your brief","Up to 3 inspected options"],"price_kobo":5000000},{"tier":"Concierge + documents","price":"₦50,000 + document pack","includes":["Everything in Concierge","Customs verification and registration handled","One point of contact to the keys"],"price_kobo":5000000},{"tier":"Concierge + tracker","price":"₦50,000 + tracker bundle","includes":["Everything in Concierge","Tracker fitted before handover","First year of monitoring"],"price_kobo":5000000}]', '[{"name":"Mrs. Amadi","area":"GRA Phase 2","quote":"I sent my brief at night and had three inspected options by Thursday. Only one had papers that were actually clean, and that is the one they pushed me towards."},{"name":"Fleet officer, oil & gas firm","area":"Port Harcourt","quote":"We asked for four cars with the same brief. They came back with options, prices and documents in one document we could circulate internally."}]', 194, 'request', 'Up to 3 inspected options in 48–72 hours, or the retainer comes back to you.'),
  ('documents', 'Customs & Document Services', 'Customs verification, registration, licence renewal, tinted permit and insurance — handled.', 'file-check', 3000000, 'Request service', 30, 1, 'Customs verification, registration, licence renewal, tinted permit and insurance — handled by people who do it every week, with photos of your papers at every stage.', '[{"title":"Customs verification","copy":"We verify that the duty paid matches the vehicle and VIN — the check that stops a cheap car becoming an expensive mistake."},{"title":"Registration & plate transfer","copy":"Documents lodged with the agency and followed up, so you are not the one queueing."},{"title":"Licence renewal","copy":"Driver’s and vehicle licence renewals, with the receipt sent to you the day it is issued."},{"title":"Tinted permit","copy":"Permit applications for tinted glass, including the checks the police will ask for at a checkpoint."},{"title":"Insurance placement","copy":"Third party or comprehensive, quoted from partner underwriters and placed in your name."},{"title":"Document wallet","copy":"Everything you paid for, scanned and stored in your account — so a lost paper is not a lost week."}]', '["Document verification against your VIN and engine number","Agency and permit fees at cost, itemised on your invoice","Photo evidence of every paper we handle","Status updates on WhatsApp without you chasing","Scanned copies in your account when it is done"]', '["Fines or penalties already incurred on the vehicle — these are payable by the owner at the time","Court-ordered or disputed ownership cases","Papers for vehicles physically outside Nigeria"]', '[{"title":"Tell us what you need","copy":"Pick the service, upload photos of the papers you already have.","timeline":"5 minutes"},{"title":"We quote and confirm","copy":"A written quote itemising agency fees, our fee and the timeline. No hidden lines.","timeline":"Within 1 working day"},{"title":"You pay, we file","copy":"Payment moves through protected channels and we start the same day.","timeline":"Same day"},{"title":"We chase it down","copy":"Every agency step gets a photo and a message. You will know before you ask.","timeline":"7–14 working days"},{"title":"Handover","copy":"Original documents handed over in PH, scans stored in your account.","timeline":"On completion"}]', '[{"tier":"Customs verification","price":"from ₦30,000","includes":["Duty and VIN cross-check","Written verification report","Advice if the papers do not match"],"price_kobo":3000000},{"tier":"Registration & plates","price":"from ₦85,000","includes":["Agency fees at cost","Lodgement and follow-up","Receipts and scans in your account"],"price_kobo":8500000},{"tier":"Full document pack","price":"from ₦150,000","includes":["Verification + registration + insurance","Tinted permit where eligible","One point of contact end to end"],"price_kobo":15000000}]', '[{"name":"Ngozi I.","area":"Peter Odili Road","quote":"The verification caught that the duty paper did not match the VIN. That one check saved me from a car I could never have registered."}]', 388, 'documents', 'Most documents complete in 7–14 working days.'),
  ('sell-swap', 'Sell or Swap Your Car', 'Free valuation within 24 hours from live network data, then we sell or swap it.', 'repeat', NULL, 'Get valuation', 40, 1, 'A free valuation within 24 hours from live network data, then we sell it for you or swap it into the car you actually want. No tyre-kickers, no “bring your papers and we will see”.', '[{"title":"Valuation from live data","copy":"Priced against what cars like yours are actually selling for in Port Harcourt this month — not a guess from a book."},{"title":"Photography that sells it","copy":"The full shot list — front ¾, rear ¾, interior, dash, engine, odometer — taken properly, once."},{"title":"Buyers who are filtered","copy":"We field the calls, screen the “last price?” merchants, and only bring you people who can pay."},{"title":"Optional certification","copy":"An inspection that earns your car the HonestCars-Certified grade and a higher price positioning."},{"title":"Swap matching","copy":"If you are upgrading, we search for your next car while selling this one, and you only pay the difference."},{"title":"Paperwork handled","copy":"Transfer, registration and change of ownership completed so there is no comeback on you later."}]', '["Free valuation within 24 hours","Listing on HonestCars with photography","Buyer screening and viewings coordination","Negotiation on your behalf","Document transfer support at close"]', '["Outstanding fines, liens or loans on the vehicle — these must be cleared before sale","Repair work before sale (we can quote it, you decide)","Guaranteed sale price — valuations are ranges, final price is the market’s"]', '[{"title":"Tell us about the car","copy":"Basics, condition, documents status and photos. Ten minutes, and you can finish it later if you are interrupted.","timeline":"10 minutes"},{"title":"Valuation","copy":"A range with the reasoning, plus the price a certified example would fetch.","timeline":"Within 24 hours"},{"title":"We list and screen","copy":"Photos, listing, buyer calls and viewings — all handled.","timeline":"Days 2–10"},{"title":"Deal and paperwork","copy":"We negotiate, you approve, documents transfer cleanly.","timeline":"Days 10–14"}]', '[{"tier":"Sell for me","price":"commission on sale","includes":["Valuation, photography and listing","Buyer screening and viewings","Negotiation and paperwork"],"price_kobo":null},{"tier":"Sell + certification","price":"commission + inspection fee","includes":["Everything in Sell for me","Inspection and Certified grade","Higher price positioning"],"price_kobo":null},{"tier":"Swap","price":"commission on sale + search fee","includes":["Everything in Sell for me","Concierge search for your next car","You pay only the difference"],"price_kobo":null}]', '[{"name":"Blessing O.","area":"Ada George","quote":"They valued it on Tuesday, listed it Wednesday, and I signed on the following Monday. I did not take a single “last price” call."}]', 158, 'request', 'Valuation within 24 hours; most sales close inside 14 days.'),
  ('tracking', 'Car Tracking & Security', 'Standard, Premium and Fleet tracker bundles installed in Port Harcourt, with renewal handled.', 'shield', 4500000, 'See bundles', 50, 1, 'Standard, Premium and Fleet tracker bundles fitted in Port Harcourt, with monitoring, geofencing and a renewal we remind you about before it lapses — not after.', '[{"title":"Fitted, not posted","copy":"An installer comes to your home or office in PH and hides the unit properly. No loose wiring under the dash."},{"title":"Live location","copy":"See your car on a map from your phone, with movement history for the last 90 days."},{"title":"Geofencing & alerts","copy":"Get a message if the car moves outside a zone you draw, at a time it should be parked, or above a speed you set."},{"title":"Immobiliser options","copy":"Remote fuel cut on Premium and Fleet, so a stolen car can be stopped rather than chased."},{"title":"Fleet view","copy":"Fleet bundles include one dashboard for every vehicle, driver behaviour and monthly reporting."},{"title":"Renewal that does not lapse","copy":"Subscription tracked in our system; you get a reminder at 30, 7 and 1 day, and you can renew online."}]', '["Device, SIM and first-year monitoring subscription","Professional installation in Port Harcourt","Mobile app access with 90-day history","Geofence and movement alerts by WhatsApp or SMS","Replacement reminder before renewal"]', '["Recovery operations — we hand the location to the police and your insurer, we do not run a chase unit","Damage to a vehicle during recovery by third parties","Installation outside Rivers State (arrangeable, travel quoted separately)"]', '[{"title":"Pick a bundle","copy":"Standard, Premium or Fleet. We tell you plainly what each one will not do.","timeline":"5 minutes"},{"title":"Book the install slot","copy":"Choose a time and place. Home, office or the lot where you are collecting the car.","timeline":"2 minutes"},{"title":"Installation","copy":"A technician fits and tests the unit, then shows you the app on your own phone.","timeline":"45–60 minutes"},{"title":"Activation","copy":"Platform activated, alerts configured and the subscription clock started.","timeline":"Same day"},{"title":"Renewals","copy":"Reminders at 30, 7 and 1 day, and online renewal so cover never lapses.","timeline":"Annual"}]', '[{"tier":"Standard","price":"from ₦45,000","includes":["Live location + 90-day history","Geofence alerts","First-year subscription"],"price_kobo":4500000},{"tier":"Premium","price":"from ₦85,000","includes":["Everything in Standard","Remote fuel cut","Tow and impact alerts"],"price_kobo":8500000},{"tier":"Fleet","price":"quoted per vehicle","includes":["Everything in Premium","Fleet dashboard + driver scorecards","Monthly reporting and account manager"],"price_kobo":null}]', '[{"name":"Emeka N.","area":"Rumuokoro","quote":"Installed in my compound on a Saturday morning. The renewal reminder came a month early, which is the opposite of every other service I pay for."}]', 271, 'install', 'Installation within 48 hours of booking in Port Harcourt.'),
  ('hire', 'Car Hire', 'Daily, weekly and corporate hire with or without a driver — airport pickup available.', 'car', NULL, 'Request quote', 60, 1, 'Daily, weekly and corporate hire with or without a driver, including Omagwa airport pickup. Vetted cars, real invoices, and a replacement if anything fails.', '[{"title":"A car that turns up","copy":"Serviced, insured, tracked and fuelled, delivered where you asked for it.","phone":true},{"title":"Driver or self-drive","copy":"Vetted drivers who know Port Harcourt, or the keys in your hand if you prefer."},{"title":"Airport pickup","copy":"Omagwa arrivals met with a name board, including the delayed-flight version of that plan."},{"title":"Corporate terms","copy":"RFQ, PO and invoice paperwork that finance departments actually accept, with monthly consolidated billing available."},{"title":"Replacement guarantee","copy":"If the vehicle fails during your hire, a replacement is dispatched — you are not left roadside in the rain."},{"title":"Tracking on every unit","copy":"Every hire vehicle carries a tracker, which is as much for your safety as our asset protection."}]', '["Comprehensive insurance and tracker on every vehicle","Routine maintenance and a 24-hour breakdown line","Airport pickup at Omagwa on request","Written quote with no hidden mileage surprises","Invoice with TIN for corporate accounts"]', '["Traffic fines incurred during the hire period","Fuel beyond the first tank on self-drive hires","Damage excess, which is stated on the quote before you sign","Interstate trips without prior agreement (they are allowed, just tell us)"]', '[{"title":"Send the request","copy":"Dates, vehicle class, with or without driver, airport pickup, and where you need it.","timeline":"3 minutes"},{"title":"Quote","copy":"Written quote with rates, deposit and mileage terms.","timeline":"Within 2 hours"},{"title":"Booking and deposit","copy":"Deposit secures the vehicle; balance on delivery or on account for corporate clients.","timeline":"Same day"},{"title":"Delivery and return","copy":"Vehicle delivered and inspected on both ends with a damage sheet.","timeline":"Your dates"}]', '[{"tier":"Self-drive daily","price":"from ₦35,000/day","includes":["Comprehensive insurance","Tracker and 24-hour support","First tank of fuel"],"price_kobo":3500000},{"tier":"With driver","price":"from ₦50,000/day","includes":["Everything in Self-drive","Vetted driver, 10 hours a day","Fuel within Port Harcourt"],"price_kobo":5000000},{"tier":"Corporate / project","price":"quoted","includes":["Monthly consolidated invoicing","Dedicated account manager","Framework rates for a project term"],"price_kobo":null}]', '[{"name":"Fleet officer, oil & gas firm","area":"Port Harcourt","quote":"Four vehicles for a two-week rotation, proper invoices, and the replacement arrived within an hour when one developed a fault."}]', 342, 'request', 'Quote within 2 hours; corporate RFQs within 1 working day.'),
  ('research', 'Research & Reports', 'TCO reports, auction sourcing analysis and market price checks, delivered in 48–72 hours.', 'bar-chart', 3500000, 'Order a report', 70, 1, 'Reports for people making a decision worth millions: total cost of ownership over five years, auction sourcing analysis, and an honest price check on a car you are about to buy.', '[{"title":"TCO report","copy":"Five-year cost of ownership for a specific model: fuel at real PH consumption, parts, servicing, insurance, depreciation and the resale band."},{"title":"Auction sourcing analysis","copy":"What a specific grade actually lands at when you add duty, clearing, transport and the surprises. The number on the auction sheet is not the number you pay."},{"title":"Market price check","copy":"An independent read on whether a car you are looking at is priced fairly against live network data, in writing."},{"title":"Written, not verbal","copy":"A PDF you can send to a partner, a company finance team or your own future self."},{"title":"Live data","copy":"Built from our live inventory and price-band table, refreshed weekly — not from articles written three years ago."},{"title":"A call to walk through it","copy":"30 minutes with the analyst who wrote it, included."}]', '["Custom research against your brief","PDF delivered to your account","A 30-minute walkthrough call","Data appendix so you can check our working"]', '["Guaranteed outcomes — these are estimates with stated assumptions","Vehicle inspection (that is a separate service)","Investment or tax advice"]', '[{"title":"Choose the report","copy":"TCO, auction analysis or price check.","timeline":"2 minutes"},{"title":"Send the brief","copy":"The model, year, usage and the decision you are trying to make.","timeline":"5 minutes"},{"title":"We research","copy":"Live listings, price bands, parts pricing from PH suppliers and fuel data.","timeline":"48–72 hours"},{"title":"You get the file","copy":"PDF in your account, plus the walkthrough call.","timeline":"Day 3"}]', '[{"tier":"Market price check","price":"₦35,000","includes":["One model, one price question","Written verdict with comparables","48-hour delivery"],"price_kobo":3500000},{"tier":"TCO report","price":"₦75,000","includes":["Five-year cost model","Fuel, parts, service, insurance, depreciation","Walkthrough call"],"price_kobo":7500000},{"tier":"Auction sourcing analysis","price":"₦120,000","includes":["Landed-cost model for a specific lot","Duty and clearing assumptions","Risk notes and inspection plan"],"price_kobo":12000000}]', '[{"name":"Adaora K.","area":"Trans-Amadi","quote":"The TCO report talked me out of the V6 I wanted and into a car I can actually run. That is the first time a report has saved me money instead of costing me."}]', 96, 'request', 'Delivered to your account within 48–72 hours.'),
  ('consultation', 'Paid Consultation', '30 minutes with someone who buys cars in Port Harcourt for a living. Bring your shortlist.', 'video', 1000000, 'Book 30 minutes', 80, 1, 'Thirty minutes with someone who buys cars in Port Harcourt for a living. Bring your shortlist, your budget and your doubts; leave with a decision you can act on.', '[{"title":"A straight opinion","copy":"We tell you which of your shortlisted cars we would buy and which one we would walk away from — and why."},{"title":"Budget reality check","copy":"What your budget actually buys in PH this month, including the running costs people forget."},{"title":"Paperwork briefing","copy":"What to check on customs, registration and duty before you pay anyone."},{"title":"Negotiation lines","copy":"The specific facts from your inspection report that move a dealer’s price."},{"title":"A written summary","copy":"Notes from the call in your account, so you do not have to remember it in the dealer’s office."}]', '["30-minute video or phone call with a senior team member","Pre-call review of any listings you send us","Written summary afterwards","Follow-up question by WhatsApp within 7 days"]', '["Physical inspection of a specific car (book that separately)","Legal advice on ownership disputes","Dealer introductions where you have not asked for them"]', '[{"title":"Pick a slot","copy":"See real availability and choose a time that works.","timeline":"2 minutes"},{"title":"Tell us about the decision","copy":"Short brief and any listings you want us to look at first.","timeline":"5 minutes"},{"title":"The call","copy":"Thirty focused minutes. Bring your questions, including the awkward ones.","timeline":"30 minutes"},{"title":"Summary and follow-up","copy":"Notes in your account and a week of WhatsApp follow-up.","timeline":"Same day"}]', '[{"tier":"Single session","price":"₦10,000","includes":["30-minute call","Written summary","7 days of follow-up"],"price_kobo":1000000},{"tier":"Three sessions","price":"₦25,000","includes":["Three calls over the buying process","Listing review between calls","Priority scheduling"],"price_kobo":2500000},{"tier":"Corporate briefing","price":"quoted","includes":["Session for a fleet or procurement team","Tailored to your vehicle policy","Written briefing pack"],"price_kobo":null}]', '[{"name":"Ibrahim S.","area":"Choba","quote":"He looked at the two adverts I sent, named the faults each one would have before I even inspected them, and was right about both."}]', 143, 'consultation', 'Slots same week, video call link issued instantly.'),
  ('parts', 'Spare-Parts Sourcing', 'VIN-matched parts sourced with escrow-protected milestone payment — not guesswork.', 'package', NULL, 'Request a part', 90, 1, 'VIN-matched parts sourced from suppliers we buy from ourselves, with escrow-protected milestone payment. No guessing, no “it will fit”, no disappearing deposit.', '[{"title":"VIN-matched, not guessed","copy":"We match to your VIN and engine code so the part fits the car you actually own."},{"title":"Sourced from real suppliers","copy":"Local PH suppliers and importers we have a history with, with the option of genuine or OEM-grade parts priced side by side."},{"title":"Escrow-protected payment","copy":"Funds sit with us and release at milestones — part confirmed, part delivered, part fitted."},{"title":"Fitment arrangement","copy":"A workshop that knows the model, with the labour quoted before it starts."},{"title":"Warranty in writing","copy":"What the supplier will and will not cover, written on the quote rather than promised on a phone call."}]', '["VIN and engine code matching","Written quote with genuine vs OEM-grade options","Escrow milestone payment","Delivery in Port Harcourt and fitment referral","Supplier warranty documented"]', '["Fitting fees are quoted separately unless you ask for them bundled","Parts for vehicles we cannot identify by VIN","Customs clearance on special imports beyond the quoted window"]', '[{"title":"Send the VIN and the part","copy":"Photos of the old part help. So does the fault code.","timeline":"5 minutes"},{"title":"Quote","copy":"Written quote with options, lead time and warranty terms.","timeline":"Within 24 hours"},{"title":"You fund the escrow","copy":"Money moves to a protected milestone, not to a stranger.","timeline":"Same day"},{"title":"Part sourced and delivered","copy":"Milestone released when the part is confirmed and delivered.","timeline":"5–10 days"},{"title":"Fitment","copy":"Fitted at a workshop that knows the platform, if you want it.","timeline":"1 day"}]', '[{"tier":"Sourcing","price":"from ₦15,000 sourcing fee","includes":["VIN matching and quote","Supplier comparison","Escrow protection"],"price_kobo":1500000},{"tier":"Sourcing + fitment","price":"from ₦25,000 + labour","includes":["Everything in Sourcing","Workshop booking","Post-fitment check"],"price_kobo":2500000},{"tier":"Fleet parts account","price":"quoted","includes":["Account terms for fleets","Consolidated monthly invoicing","Priority sourcing"],"price_kobo":null}]', '[{"name":"Godwin E.","area":"Elelenwo","quote":"Two shops sold me the wrong gearbox mount before these people matched it to the VIN. Third one fitted first time."}]', 205, 'request', 'Quote within 24 hours; most parts land in PH within 5–10 days.'),
  ('dealer-services', 'B2B: Dealer Services', 'Media shoots, featured placement and market intelligence for lots in Port Harcourt.', 'store', NULL, 'See packages', 100, 1, 'Media shoots, featured placement and market intelligence for lots in Port Harcourt. We bring you buyers; you keep selling the way you already do.', '[{"title":"Media shoot","copy":"The full shot list per car, photographed to a consistent standard, delivered as web-ready files."},{"title":"Featured placement","copy":"Your stock in the homepage feed and the curated facet pages buyers actually browse."},{"title":"Lead routing","copy":"Enquiries on your listings sent to your phone the moment they land, with the buyer’s name and number."},{"title":"Performance reporting","copy":"Views, enquiries and response-time scorecard per listing, so you can see what sells and what sits."},{"title":"Market intelligence","copy":"Weekly price-band updates for the models on your lot, so you price to sell rather than to hope."},{"title":"No lock-in","copy":"Month to month. If we do not bring you buyers, you stop — there is no annual contract to argue about."}]', '["Photography and listing preparation per car","Listing moderation and quality control","Lead routing by WhatsApp and portal inbox","Monthly performance report","Dealer portal access (phase 2)"]', '["Any cut of your sale price beyond the agreed commission","Inspection of your stock (that is a paid service, priced separately)","Guaranteed sales volumes"]', '[{"title":"Apply","copy":"Tell us about the lot: location, size, what you sell and how you document your cars.","timeline":"5 minutes"},{"title":"Site visit and agreement","copy":"We look at your stock and your paperwork, and agree commission terms in writing.","timeline":"Within 5 working days"},{"title":"Shoot and list","copy":"Media day, then listings live after moderation.","timeline":"Within 10 days"},{"title":"Leads and reporting","copy":"Leads to your phone, performance in your portal, review each month.","timeline":"Ongoing"}]', '[{"tier":"Listed","price":"commission per sale","includes":["Listings and moderation","Lead routing","Monthly report"],"price_kobo":null},{"tier":"Listed + media","price":"commission + shoot fee","includes":["Everything in Listed","Professional media shoot per car","Featured placement on new stock"],"price_kobo":null},{"tier":"Featured partner","price":"retainer or commission","includes":["Everything in Listed + media","Homepage and facet placement","Price intelligence subscription"],"price_kobo":null}]', '[{"name":"Aba Road Autos","area":"Aba Road","quote":"The photos alone changed how many calls we get. Buyers arrive already knowing the mileage and the papers, which saves everybody a wasted Saturday."}]', 74, 'request', 'Shoot booked within 5 working days; leads routed to your phone same day.');
INSERT INTO pages (`slug`, `title`, `h1`, `hero_copy`, `meta_title`, `meta_description`, `body`, `indexable`, `legal_review`) VALUES
  ('how-it-works', 'How HonestCars works', 'How it works, end to end', 'Five steps from “I need a car” to keys, papers and a tracker in your hand — with the verification happening before you pay, not after.', 'How HonestCars works — verification, pricing and protected purchase', 'How HonestCars buys, verifies, prices and hands over cars in Port Harcourt: the checklist, the grades, the documents and the protected payment steps.', '[{"type":"heading","text":"The short version"},{"type":"stats","items":[{"value":"3","label":"verification grades, no grey areas"},{"value":"48–72h","label":"concierge shortlist SLA"},{"value":"≤4h","label":"inspection report after the check"},{"value":"7–14 days","label":"typical document turnaround"}]},{"type":"heading","text":"Step by step"},{"type":"checklist","items":["You browse verified stock, or send a brief to the concierge.","We establish what the car actually is: inspection, documents, faults, mileage.","We price it against live market bands for the model, year and condition — and tell you where it sits.","You pay through HonestCars-protected channels, never to a seller directly.","Documents transfer, the car is handed over, and any tracker or insurance is fitted on the same day."]},{"type":"callout","tone":"amber","title":"The part most buyers do not expect","text":"If the inspection finds something that changes the value, we tell you before you pay and renegotiate or walk away. We would rather lose a sale than run a buyer through a car we do not believe in."},{"type":"heading","text":"What we check, every time"},{"type":"table","head":["Check","What it means for you"],"rows":[["OBD2 scan","Fault codes read and photographed, including stored history"],["Panel and chassis","Paint depth, panel gaps and jig marks — where accident repairs hide"],["Flood tell-tales","Wiring loom, seat rails and spare-wheel well inspected"],["Documents","Customs, registration and duty status sighted and verified"],["Road test","Gearbox, suspension, brakes and steering on real PH roads"],["Honest note","The faults, named in writing, on the listing"]]},{"type":"heading","text":"Where the money goes"},{"type":"paragraph","text":"You pay HonestCars for the service: inspection, concierge, documents, tracking, hire. On a car purchase handled through us, milestones release to the seller only when each stage is confirmed — inspection passed, documents verified, handover complete."},{"type":"quote","text":"We do not take money from sellers to make a car look good. That single rule is the whole business.","attribution":"Raph Nicks, Head of Inspections"},{"type":"heading","text":"Still not sure where to start?"},{"type":"paragraph","text":"Send the brief and we will do the searching, inspecting and negotiating. If we find nothing that meets it, the retainer comes back to you."}]', 1, 0),
  ('verification', 'Verification', 'What our badges actually mean', 'Three grades, published on every car card and every listing. The grade tells you how much of this car a human being from HonestCars has personally seen — and the difference matters more than any photo.', 'HonestCars verification — what each grade really means', 'Network-Listed, Field-Checked and HonestCars-Certified explained, plus the full inspection checklist, real catches and our integrity rules.', '[{"type":"heading","text":"The three grades"},{"type":"table","head":["Grade","What a human has done","What it does not mean"],"rows":[["Network-Listed","Nothing yet — the dealer gave us the data.","We have not seen this car. Use it for range and price only."],["Field-Checked","An inspector has physically stood next to the car and photographed it.","No OBD2 scan or document verification yet."],["HonestCars-Certified","Full checklist passed: OBD2, documents sighted, road test, honest note written.","It does not mean a new car — it means you know exactly what it is."]]},{"type":"callout","tone":"green","title":"Why we publish the bottom grade","text":"If every car looked certified, the Certified badge would be worthless. Publishing the weak grades is what makes the strong one mean something."},{"type":"heading","text":"The HonestCars checklist"},{"type":"checklist","items":["OBD2 scan — every code read and photographed, including stored history","Paint-depth readings on all panels, checked against factory ranges","Panel gaps, spot welds and jig marks inspected for structural repair","Flood tell-tales: wiring loom, seat rails, spare-wheel well, door hinges","Odometers cross-checked against service records and OBD2 history","Customs papers, registration and duty documents sighted and photographed","Road test on public roads, including cold start","Tyres, brakes, suspension and exhaust inspected on the vehicle","AC performance measured at the vents, not judged by hand","Written honest note — the faults, in plain language, on the listing"]},{"type":"heading","text":"Catches we have made this year"},{"type":"paragraph","text":"We are not publishing these to alarm you. We are publishing them because each one was found before a buyer paid — which is the only reason the badge is worth anything."},{"type":"table","head":["What the advert said","What the inspection found"],"rows":[["“First body, no accident”","Rear left quarter panel resprayed to a different paint depth; boot floor straightened"],["“Genuine 62,000 km”","Odometer 62,000 km, but service book and OBD2 history both read past 140,000 km"],["“Duty fully paid”","Duty receipt referenced a different VIN entirely — papers could not be registered"],["“Clean interior, nothing to spend”","Water tide line in the spare-wheel well and corrosion on the seat rails"],["“Ice-cold AC”","Vent temperature 18°C after ten minutes — compressor failing"],["“Just drove it from Lagos”","Front subframe damage consistent with a significant impact, repaired off-jig"]]},{"type":"heading","text":"Our integrity rules"},{"type":"checklist","items":["Inspectors never accept money, fuel, food or “transport” from a seller.","No one at HonestCars takes commission from a dealer on a buyer’s purchase.","A car that fails inspection still gets its report written — we never bury one.","We publish the bad news to the listing, not just to the buyer.","If we get something wrong, we say so publicly on the listing and fix the process."]},{"type":"quote","text":"The report is the product. If we ever shade it, we have nothing left to sell.","attribution":"HonestCars inspection team"},{"type":"callout","tone":"amber","title":"Inspection reports are opinions, not guarantees","text":"An inspection describes the car on the day it was seen, with the access the seller allowed. It is not a warranty, and it does not cover faults that develop later. See our disclaimer for the full wording."}]', 1, 0),
  ('about', 'About', 'A quiet showroom run by a straight-talker', 'Honest Cars LTD exists because buying a used car in Port Harcourt should not require a mechanic on standby, a lawyer on retainer and a strong stomach.', 'About Honest Cars LTD — Port Harcourt', 'Who we are, how we make money, and the rules we hold ourselves to as a Port Harcourt car marketplace and services company.', '[{"type":"heading","text":"Why we exist"},{"type":"paragraph","text":"The used-car market in Port Harcourt runs on information asymmetry: the seller knows, the buyer hopes. Most people solve this by bringing an uncle who “knows cars”. We built the thing that uncle was standing in for — except with a paint-depth gauge, an OBD2 scanner and a written report."},{"type":"heading","text":"What we do"},{"type":"paragraph","text":"We list verified cars from partner lots, inspect the ones buyers take seriously, handle customs and registration paperwork, arrange tracking, hire and parts — and, when someone would rather not do the hunting themselves, we do the searching and bring back up to three inspected options."},{"type":"heading","text":"How we make money"},{"type":"checklist","items":["A commission from dealers on cars sold through the platform — agreed in writing, published to the buyer on request.","Fees for services: inspections, concierge searches, document handling, tracking, hire and reports.","Subscription and media packages for partner lots."]},{"type":"callout","tone":"green","title":"What we do not do","text":"We do not take money from a seller to improve a car’s grade, and we do not take a buyer’s payment directly. Payment moves through protected channels with milestones, so the money and the car change hands at the same time."},{"type":"heading","text":"The team"},{"type":"paragraph","text":"A small Port Harcourt team: inspectors who came out of the trade, a documentation lead who knows every queue at every agency, and analysts who keep the price bands honest. Between us we have inspected hundreds of cars this year and talked more buyers out of bad cars than into them."},{"type":"stats","items":[{"value":"612","label":"inspections completed"},{"value":"12","label":"partner lots in PH"},{"value":"11","label":"services under one roof"},{"value":"48–72h","label":"concierge SLA"}]},{"type":"heading","text":"Company details"},{"type":"paragraph","text":"Honest Cars LTD is registered in Nigeria and operates from Port Harcourt, Rivers State. We work virtually — there is no showroom to visit, because inspections come to you."},{"type":"callout","tone":"amber","title":"Placeholder","text":"The CAC registration number, registered address and team names are placeholders in this build and need to be supplied before launch."}]', 1, 0),
  ('contact', 'Contact', 'Talk to a human', 'WhatsApp is the fastest way to reach us — that is where the ops team actually lives. Everything else works too, we are just slower on it.', 'Contact HonestCars — Port Harcourt', 'Reach HonestCars on WhatsApp, phone or email. We operate virtually in Port Harcourt — inspections come to you.', '[{"type":"heading","text":"How to reach us"},{"type":"table","head":["Channel","Best for","Response"],"rows":[["WhatsApp","Anything urgent, viewing requests, document updates","Minutes during working hours"],["Phone","Speak to the ops team directly","Immediate in working hours"],["Email","Invoices, corporate RFQs, formal complaints","Within 1 working day"],["This form","Detailed briefs, anything with photos attached","Within 1 working day"]]},{"type":"callout","tone":"navy","title":"We operate virtually in Port Harcourt","text":"There is no office to visit and no lot to walk around. Inspections happen at the seller’s location, handovers happen where it suits you, and documents are delivered to you."},{"type":"heading","text":"Before you write"},{"type":"checklist","items":["For a viewing, have the stock number ready — it is on every listing and card.","For a document question, send a photo of the paper you have.","For a complaint, include the stock number or tracking ID so we can pull the record."]}]', 1, 0),
  ('terms', 'Terms of Service', 'Terms of Service', 'The rules that govern using honestcarsltd.com and buying our services.', 'Terms of Service | HonestCars', 'Terms governing the use of honestcarsltd.com and the purchase of HonestCars services in Port Harcourt.', '[{"type":"callout","tone":"amber","title":"Placeholder — pending legal review","text":"This structure was built to the specification; the binding wording is being supplied by HonestCars’ legal retainer. Do not treat the text below as final legal terms."},{"type":"heading","text":"1. Who we are"},{"type":"paragraph","text":"honestcarsltd.com is operated by Honest Cars LTD, a company registered in Nigeria. References to “we”, “us” and “HonestCars” mean Honest Cars LTD."},{"type":"heading","text":"2. What this site does"},{"type":"paragraph","text":"We publish vehicle listings supplied by partner dealers, and we sell inspection, concierge, documentation, tracking, hire, parts and research services. A listing is an invitation to enquire, not an offer capable of acceptance."},{"type":"heading","text":"3. Verification grades"},{"type":"paragraph","text":"Grades describe the extent of our involvement with a vehicle, set out on our Verification page. A grade is not a warranty of condition, roadworthiness or legal title."},{"type":"heading","text":"4. Prices and payment"},{"type":"paragraph","text":"Prices shown are in Nigerian Naira and may change. Vehicle prices are set by the partner dealer. Payments for services and protected purchases are collected through our payment partners; we never store card details on our systems."},{"type":"heading","text":"5. Protected purchases"},{"type":"paragraph","text":"Where we handle a purchase, funds are held and released against agreed milestones. We are not a party to the sale contract between buyer and dealer unless we say so in writing for a specific transaction."},{"type":"heading","text":"6. Your account and content"},{"type":"paragraph","text":"You are responsible for the accuracy of information you submit and for keeping access to your phone number secure. You grant us permission to use submitted photographs and details to prepare your listing."},{"type":"heading","text":"7. Liability"},{"type":"paragraph","text":"We exclude liability to the extent permitted by law. Nothing in these terms limits liability that cannot be limited under Nigerian law, including for fraud."},{"type":"heading","text":"8. Governing law"},{"type":"paragraph","text":"These terms are governed by the laws of the Federal Republic of Nigeria, and the courts of Rivers State have jurisdiction."}]', 0, 1),
  ('privacy', 'Privacy Policy', 'Privacy Policy', 'What we collect, why we collect it, who sees it, and how to get it deleted. Written to be read, and aligned to the Nigeria Data Protection Act.', 'Privacy Policy | HonestCars', 'How HonestCars collects, uses and protects personal data under the Nigeria Data Protection Act, and how to exercise your rights.', '[{"type":"callout","tone":"amber","title":"Placeholder — pending legal review","text":"The structure below follows the NDPA-aligned requirements in the specification. Final wording is being supplied by HonestCars’ legal retainer."},{"type":"heading","text":"What we collect"},{"type":"checklist","items":["Your name and WhatsApp number, when you enquire, book or apply.","Details of the car you are selling or looking for, when you tell us.","Documents you upload, such as customs papers or a licence, for document services.","Usage data: pages visited, filters used and events fired, collected without your name attached."]},{"type":"heading","text":"Why we collect it"},{"type":"paragraph","text":"To answer your enquiry, arrange viewings and inspections, complete paperwork you have asked us to do, take payment, and improve the site. Marketing messages only go to people who opted in, and every one of them has a way out."},{"type":"heading","text":"Who sees it"},{"type":"paragraph","text":"Our ops team, and the partner dealer whose car you are enquiring about — with your number masked until a viewing is appointed. Payment partners see what they need to process a payment. We do not sell personal data, ever."},{"type":"heading","text":"How long we keep it"},{"type":"paragraph","text":"Enquiry records are kept for 24 months, transaction and document records for 7 years as required for tax and legal purposes, and analytics events without identifiers for 26 months."},{"type":"heading","text":"Your rights"},{"type":"checklist","items":["Ask for a copy of everything we hold about you.","Ask us to correct anything inaccurate.","Ask us to delete what we are not legally required to keep.","Withdraw marketing consent at any time.","Complain to the Nigeria Data Protection Commission."]},{"type":"heading","text":"Cookies and analytics"},{"type":"paragraph","text":"We use local storage to remember your shortlist and recently viewed cars on your own device. Analytics is configured with IP anonymisation and never receives your name, phone number or anything you typed into a form."},{"type":"heading","text":"Contact"},{"type":"paragraph","text":"Data requests go to our privacy contact using the details on the contact page, and are actioned within 30 days."}]', 0, 1),
  ('refunds', 'Refunds & Cancellations', 'Refunds & Cancellations', 'When you get your money back, when you do not, and how long it takes.', 'Refunds & Cancellations | HonestCars', 'HonestCars refund and cancellation terms for inspections, concierge retainers, bookings and shop orders.', '[{"type":"callout","tone":"amber","title":"Placeholder — pending legal review","text":"The policy below follows the specification and the operating model. Final wording is being supplied by HonestCars’ legal retainer."},{"type":"heading","text":"Concierge retainer"},{"type":"paragraph","text":"The retainer is credited against the success fee when you buy a car through us. If we find nothing that meets your brief inside the agreed SLA, the retainer is refunded in full — you do not have to argue for it, the refund is automatic when we close the search as unsuccessful."},{"type":"heading","text":"Inspections"},{"type":"checklist","items":["More than 24 hours before the slot: full refund or free reschedule.","Within 24 hours: one reschedule free, refund at our discretion once the inspector’s time is committed.","If we cannot attend for any reason: full refund, always, plus the reschedule at no cost.","If the seller refuses access on the day: we refund the inspection fee in full."]},{"type":"heading","text":"Bookings and consultations"},{"type":"paragraph","text":"Consultations can be rescheduled free up to 12 hours before the call. Document-handling fees are refundable until lodgement has started, after which agency fees already paid are not recoverable."},{"type":"heading","text":"Shop orders"},{"type":"paragraph","text":"Unopened products can be returned within 7 days of delivery for a refund less the delivery fee. Trackers already installed are non-refundable, but the monitoring subscription can be cancelled with pro-rata credit against a future purchase."},{"type":"heading","text":"How refunds are paid"},{"type":"paragraph","text":"Refunds return to the same payment method used, within 5–10 working days, and you get a WhatsApp confirmation when the refund is initiated rather than when it clears."}]', 0, 1),
  ('disclaimer', 'Disclaimer', 'Disclaimer', 'What our inspection reports do and do not cover, and how to read our price bands.', 'Disclaimer | HonestCars', 'Limitations of HonestCars inspection reports, price bands, market data and third-party information.', '[{"type":"callout","tone":"amber","title":"Placeholder — pending legal review","text":"The wording below reflects the specification’s intent and is pending review by HonestCars’ legal retainer."},{"type":"heading","text":"Inspection reports"},{"type":"paragraph","text":"An inspection is a professional opinion on the condition of a vehicle at the time it was examined, based on the access and conditions available that day. It is not a warranty or guarantee, and it does not cover faults that were hidden, that develop later, or that fall outside the stated checklist. Report liability is capped at the fee paid for the inspection."},{"type":"heading","text":"Price bands and market data"},{"type":"paragraph","text":"Price-position indicators and price bands are estimates produced from network listings, transaction information and analyst judgement. They are information, not valuations, and they should not be relied upon as the sole basis for a purchase, sale or financing decision."},{"type":"heading","text":"Listing information"},{"type":"paragraph","text":"Vehicle details are supplied by partner dealers and verified to the extent shown by the listing’s verification grade. Mileage is stated as recorded on the odometer unless the listing says it has been verified."},{"type":"heading","text":"Third-party services"},{"type":"paragraph","text":"Tracking, insurance and hire involve third-party providers whose own terms apply. We select partners carefully but do not control their service standards or liability."},{"type":"heading","text":"No financial or legal advice"},{"type":"paragraph","text":"Nothing on this site constitutes financial, investment, tax or legal advice, and research reports are estimates with stated assumptions rather than predictions."}]', 0, 1);
