INSERT INTO products (`slug`, `category`, `name`, `summary`, `description`, `price_kobo`, `specs`, `install_included`, `warranty_text`, `stock_status`, `delivery_options`, `image`, `position`, `is_active`) VALUES
  ('tracker-standard', 'trackers', 'Tracker — Standard', 'Live location, 90-day history and geofence alerts, fitted in Port Harcourt.', 'The bundle most buyers take. A hidden unit fitted by our installer, live location on your phone, 90 days of movement history and WhatsApp alerts when the car moves outside a zone you set. Includes the first year of monitoring.', 4500000, '[["Monitoring","12 months included"],["History","90 days"],["Alerts","Geofence, movement, ignition"],["Install","Included, within PH"],["Immobiliser","No"]]', 1, '12 months on the device, 12 months monitoring included', 'in_stock', '["pickup_meet_point","ph_delivery"]', '/img/seed/hatchback-dash.svg', 10, 1),
  ('tracker-premium', 'trackers', 'Tracker — Premium', 'Adds remote fuel cut, tow detection and impact alerts.', 'For cars that are a genuine asset rather than a convenience. Remote fuel cut so a stolen car can be stopped rather than chased, tow detection, impact alerts and the same 90-day history with a longer retention option.', 8500000, '[["Monitoring","12 months included"],["History","180 days"],["Alerts","Geofence, tow, impact, speed"],["Install","Included, within PH"],["Immobiliser","Remote fuel cut"]]', 1, '24 months on the device, 12 months monitoring included', 'in_stock', '["pickup_meet_point","ph_delivery"]', '/img/seed/suv-dash.svg', 20, 1),
  ('tracker-fleet', 'trackers', 'Tracker — Fleet unit', 'Per-vehicle unit with a fleet dashboard and driver scorecards.', 'Priced per vehicle with volume terms. Every unit reports into one dashboard with driver behaviour scoring, monthly reporting and consolidated invoicing. Includes installation and activation for each vehicle.', 6500000, '[["Monitoring","12 months per unit"],["Dashboard","Fleet view + scorecards"],["Reporting","Monthly, exportable"],["Install","Included"],["Minimum","5 units"]]', 1, '24 months on the device; subscriptions billed annually', 'in_stock', '["pickup_meet_point","ph_delivery"]', '/img/seed/pickup-dash.svg', 30, 1),
  ('obd2-scanner-basic', 'diagnostics', 'OBD2 Scanner — Basic', 'Read and clear fault codes on any post-2001 petrol or diesel car.', 'The scanner we hand to buyers who want to keep checking a car after purchase. Reads and clears engine codes, shows live sensor data and I/M readiness, and works on every OBD2 car sold in Nigeria.', 3200000, '[["Protocols","OBD2, CAN, ISO, PWM, VPW"],["Live data","Yes"],["Freeze frame","Yes"],["Works with","Android app (included)"],["Codes","Generic + manufacturer for common makes"]]', 0, '12 months replacement warranty', 'in_stock', '["pickup_meet_point","ph_delivery"]', '/img/seed/sedan-engine.svg', 10, 1),
  ('obd2-scanner-pro', 'diagnostics', 'OBD2 Scanner — Pro', 'Bidirectional scanner with ABS and airbag diagnostics.', 'For mechanics and serious owners: reads and clears ABS and airbag systems, runs actuator tests, and supports manufacturer-specific codes for Toyota, Honda, Lexus and Mercedes. Includes a hard case.', 14500000, '[["Systems","Engine, ABS, SRS, transmission"],["Bidirectional","Yes, actuator tests"],["Manufacturer codes","Toyota, Honda, Lexus, Mercedes, Ford"],["Updates","Free for 24 months"],["Case","Included"]]', 0, '12 months replacement warranty', 'low_stock', '["pickup_meet_point","ph_delivery"]', '/img/seed/suv-engine.svg', 20, 1),
  ('care-kit-essentials', 'care_kits', 'Care Kit — Essentials', 'Everything for the first month of ownership, in one bag.', 'Put together after watching what new owners actually buy in their first month: coolant, engine oil top-up, screen wash, microfibre set, tyre gauge, jump leads, a torch and a printed copy of our owner checklist.', 2800000, '[["Includes","Oil top-up, coolant, screen wash"],["Tools","Jump leads, gauge, torch, microfibres"],["Extras","Owner checklist booklet"],["Bag","Reusable, boot-sized"]]', 0, NULL, 'in_stock', '["pickup_meet_point","ph_delivery"]', '/img/seed/hatchback-interior.svg', 10, 1),
  ('care-kit-detailing', 'care_kits', 'Care Kit — Detailing', 'Interior and exterior detailing set for PH conditions.', 'Built for the reality of Harmattan dust and rainy-season mud: wash and wax, interior cleaner, dashboard protectant that does not turn plastic shiny, glass treatment and clay bar for overspray.', 4200000, '[["Exterior","Wash, wax, clay bar"],["Interior","Cleaner + matt protectant"],["Glass","Hydrophobic treatment"],["Applicators","Included"]]', 0, NULL, 'in_stock', '["pickup_meet_point","ph_delivery"]', '/img/seed/sedan-interior.svg', 20, 1),
  ('care-kit-roadside', 'care_kits', 'Care Kit — Roadside', 'For the boot: pressure, power, light and a way to call for help.', 'Tyre compressor and sealer, quality jump leads, hi-vis vest, triangle, first-aid kit, 12V work light and a printed card with every number you might need on a bad night on the East-West road.', 5500000, '[["Tyre","Compressor + sealer"],["Electrical","Jump leads, 12V lamp"],["Safety","Vest, triangle, first aid"],["Extras","Emergency numbers card"]]', 0, '12 months on the compressor', 'in_stock', '["pickup_meet_point","ph_delivery"]', '/img/seed/van-interior.svg', 30, 1);
INSERT INTO service_requests (`tracking_id`, `type`, `status`, `name`, `phone`, `brief`, `sla_due_at`, `source_path`, `notes`) VALUES
  ('HC-2481', 'concierge', 'options_ready', 'Demo buyer (seeded record)', '08030000000', '{"budget_min":8000000,"budget_max":13000000,"makes":["Toyota","Honda"],"body_types":["sedan","suv"],"transmission":"automatic","must_haves":["AC must chill","low mileage","first-car friendly"],"intended_use":"family","timeline":"two_weeks","financing":"no","addons":["inspection_included"]}', '2026-10-04 00:00:00', '/find-my-car', 'Seeded demo record used by the reviewer to open the concierge status page.');
INSERT INTO testimonials (`customer_name`, `area`, `quote`, `service_tag`, `rating`, `position`, `is_published`) VALUES
  ('Chidi O.', 'Woji', 'They told me the Camry I liked had a resprayed boot lid before I paid for the inspection. No other lot would have said that. I bought it anyway, with my eyes open.', 'inspection', 5, 1, 1),
  ('Mrs. Amadi', 'GRA Phase 2', 'I sent my brief on WhatsApp at night and had three inspected options by Thursday. The swap was handled end to end — I only showed up to sign.', 'concierge', 5, 2, 1),
  ('Emeka N.', 'Rumuokoro', 'The tracker was installed in my compound and the renewal reminder came before I even thought about it. Small thing, but it means they are watching.', 'tracking', 5, 3, 1),
  ('Tunde A.', 'Trans-Amadi', 'Documents were the part I dreaded. Customs verification and registration were done in nine days and I got updates without chasing anybody.', 'documents', 5, 4, 1),
  ('Ngozi I.', 'Peter Odili Road', 'I have bought two cars through HonestCars. The second one they talked me out of a bad buy and into a better one. That is why I came back.', 'sell-swap', 5, 5, 1),
  ('Fleet officer, oil & gas firm', 'Port Harcourt', 'We needed four hire vehicles for a two-week rotation with proper invoices. Quote, paperwork and tracking proposals all arrived in one day.', 'hire', 5, 6, 1);
INSERT INTO blog_posts (`slug`, `title`, `category`, `excerpt`, `hero_image`, `hero_alt`, `author_name`, `author_role`, `read_minutes`, `status`, `published_at`, `is_featured`, `make_tags`, `body`, `service_cta`, `author_bio`, `meta_title`, `meta_description`) VALUES
  ('2015-toyota-camry-honest-buyers-guide', 'The 2015 Toyota Camry: what ₦12m actually buys in Port Harcourt', 'honest_buyers_guide', 'We put a 2015 Camry through the full checklist and wrote down everything — the good, the tired and the priced-in.', '/img/seed/og-default.svg', '2015 Toyota Camry inspection in Port Harcourt', 'Raph Nicks', 'Head of Inspections', 9, 'published', '2026-09-28 00:00:00', 1, '["Toyota"]', '[{"type":"paragraph","text":"A 2015 Camry is the [default sensible buy in Port Harcourt](/cars?make=Toyota), and that is exactly why you should be suspicious of it. Popular models attract the most repair-and-flip activity, because there is always a buyer."},{"type":"paragraph","text":"We put three 2015 Camrys through the full checklist in the same week. Here is what ₦12m bought in each case, with the numbers."},{"type":"heading","text":"What ₦12m buys in this market"},{"type":"table","head":["Car","Asking","Mileage","Grade","Notable finding"],"rows":[["Camry LE, 2015","₦11.8m","88,000 km","Certified","Clean; two panels resprayed, priced in"],["Camry SE, 2015","₦12.4m","62,000 km","Field-Checked","Odometer inconsistent with service book"],["Camry XLE, 2015","₦13.2m","104,000 km","Certified","AC compressor weak; rear bushings due"]]},{"type":"callout","tone":"amber","title":"The one that looked best was the worst","text":"The lowest-mileage car had the most inconsistent paperwork. A 62,000 km reading on a ten-year-old car is possible — it is just rare enough that the odometer history has to survive scrutiny."},{"type":"heading","text":"The five things that actually decide the price"},{"type":"checklist","items":["Odometer consistency: service book, OBD2 history and physical wear all have to agree.","Panel history: paint-depth readings on all four quarters, and the boot floor for accident repair.","AC performance: measured at the vent. “Blows cold” is not a measurement.","Suspension and bushings: Port Harcourt roads eat them, and the repair bill is real.","Document status: customs verified and duty sighted, or a discount that reflects the missing papers."]},{"type":"heading","text":"What we would pay"},{"type":"paragraph","text":"For a clean 2015 Camry with verified mileage, complete papers and everything working: ₦10.5m–₦12.5m depending on trim and km — compare that against [the Camrys we have actually inspected](/cars?make=Toyota&model=Camry). Below ₦10m, start asking what is wrong, because something usually is."},{"type":"quote","text":"The cheapest Camry on the road is rarely the cheapest Camry to own.","attribution":"Raph Nicks"},{"type":"heading","text":"Before you pay for one"},{"type":"paragraph","text":"Book the [inspection](/services/inspection), not the car. Any inspection we do lands in writing, names the faults and stays attached to the listing — including the faults that cost the seller money."}]', 'inspection', 'Raph Nicks leads HonestCars inspections in Port Harcourt. He has inspected more than 600 used cars and has talked more buyers out of bad ones than into them.', 'The 2015 Toyota Camry: what ₦12m buys in Port Harcourt', 'Three 2015 Camrys, the same week, the same checklist. What a clean one is worth, what the tired ones hide, and what to check before you pay.'),
  ('tokunbo-vs-nigerian-used-ph', 'Tokunbo vs Nigerian-used: the honest maths for Port Harcourt buyers', 'market_intel', 'A cheaper import is not always cheaper. Here is the running-cost maths we run for buyers before they commit.', '/img/seed/og-default.svg', 'Comparing tokunbo and Nigerian-used cars in Port Harcourt', 'Ada George', 'Market Analyst', 7, 'published', '2026-09-24 00:00:00', 0, '["Toyota","Honda"]', '[{"type":"paragraph","text":"The reflex is “tokunbo is better”. The maths is not that simple, especially once you add registration, clearing and the first six months of repairs. Worth saying up front: you can inspect [either kind of car](/cars) the same way, on the same checklist."},{"type":"heading","text":"The cost lines people forget"},{"type":"table","head":["Cost","Tokunbo","Nigerian-used"],"rows":[["Duty and clearing","Landed in the asking price","Usually already paid and verified"],["First-year repairs","Higher — systems have sat unused","Lower if the owner drove it properly"],["Document risk","Mismatched papers are common","Papers usually already registered here"],["Depreciation","Already taken the big hit","Flatter curve from here"]]},{"type":"callout","tone":"navy","title":"The rule of thumb we use","text":"If the Nigerian-used car has a verifiable service history and the tokunbo does not, the Nigerian-used car usually wins on five-year cost — even when it is a year older."},{"type":"heading","text":"Where tokunbo wins"},{"type":"checklist","items":["You want specific trim or options that rarely get ordered here.","You want a platform with fewer miles on Nigerian roads, which matters for suspension.","You are buying a grade you can verify before shipping, not after — an [import inspection](/services/inspection) or a [research brief](/services/research) does that."]},{"type":"heading","text":"Where Nigerian-used wins"},{"type":"checklist","items":["Papers are already clean and registered in Nigeria.","You can inspect the actual car in person, today, with its service history.","The seller is the long-term owner rather than a trader who has had it three weeks. Cars with the full [Customs verified](/verification) status are the ones to compare."]}]', 'consultation', 'Ada George analyses the Port Harcourt market for HonestCars, building the price bands behind every listing.', 'Tokunbo vs Nigerian-used: the honest maths for PH', 'A cheaper import is not always cheaper. The five-year cost lines we actually add up for Port Harcourt buyers, and when each side wins.'),
  ('odometer-fraud-check-yourself', 'How to check an odometer yourself before you pay a deposit', 'honest_buyers_guide', 'Seven checks anyone can do in ten minutes, plus the two tricks dealers use to reset a mileage that still fool buyers.', '/img/seed/og-default.svg', 'Odometer close-up during a HonestCars inspection', 'Raph Nicks', 'Head of Inspections', 6, 'published', '2026-09-20 00:00:00', 0, '["Toyota"]', '[{"type":"paragraph","text":"Odometer fraud is the most common lie in the used-car market, and the easiest to catch if you know where the car keeps its own records. If you would rather not do it yourself, every [HonestCars inspection](/services/inspection) includes an OBD2 read and an odometer verdict."},{"type":"heading","text":"Seven checks you can do in ten minutes"},{"type":"checklist","items":["Service book: look for a chain of stamps whose km readings increase consistently with the dates.","OBD2 history: stored distance and fault snapshots often carry a higher figure than the dash.","Driver’s seat bolster and pedals: wear should match the claimed km.","Steering wheel and gear knob: shine and worn leather betray high mileage.","Suspension bushings: at 150,000 km they have usually been replaced, and the receipts prove it.","Windscreen: original glass with a manufacturer date before the car’s build year is a tell.","Tyre dates: four tyres stamped years apart suggest replacements driven by distance — the same quick read we do on every [field inspection](/services/inspection)."]},{"type":"callout","tone":"amber","title":"The two tricks that survive all of the above","text":"A worn interior can be swapped from a scrap car, and a service book can be forged entirely. If the numbers only come from the book and the interior, get an OBD2 read — the ECU keeps its own distance in most modern cars, and that is the number a seller cannot reach."},{"type":"heading","text":"What it costs you when you miss it"},{"type":"paragraph","text":"A 60,000 km car priced against a 140,000 km one typically carries a ₦1.5m–₦3m premium. That is the size of the bet you are making when you take the number on trust. Every [car in the listings](/cars) shows its grade openly, and the ones we have physically checked say so."}]', 'inspection', 'Raph Nicks leads HonestCars inspections in Port Harcourt and has written the checklist every inspector works to.', 'How to check an odometer before you pay a deposit', 'Seven checks anyone can do in ten minutes, the two tricks that survive them all, and the ₦1.5m–₦3m you are betting when you trust the dash.'),
  ('customs-papers-explained', 'Customs papers, explained without the jargon', 'ownership_maintenance', 'What "duty sighted" really means, what happens if papers are missing, and how to verify them yourself.', '/img/seed/og-default.svg', 'Verifying customs documents for a car in Port Harcourt', 'Chinelo U.', 'Documentation Lead', 8, 'published', '2026-09-16 00:00:00', 0, '["Toyota"]', '[{"type":"paragraph","text":"“Duty paid” and “duty sighted” are not the same statement, and the difference is the difference between a car you can register and a car you cannot. Our [documentation service](/services/documents) exists because of how often that sentence comes back to bite people."},{"type":"heading","text":"The words, translated"},{"type":"table","head":["Term","What it actually means"],"rows":[["Duty paid","Someone says the import duty was paid. There is no document in front of you."],["Duty sighted","We have looked at the duty document and checked its reference against the VIN."],["Customs verified","The paperwork reconciles with the vehicle: VIN, engine number and entry reference all agree."],["Registration complete","The vehicle is on the Nigerian register in an owner’s name and transfer can be lodged."]]},{"type":"callout","tone":"green","title":"The check that matters most","text":"Match the VIN on the customs document to the VIN on the chassis. If they disagree, nothing else about the papers matters — you are looking at a car you may never be able to register."},{"type":"heading","text":"What to do when papers are missing"},{"type":"checklist","items":["Get the missing-papers discount in writing before you commit to anything.","Confirm the vehicle is not flagged before you spend on repairs.","Budget [the document service](/services/documents) and the timeline — 7 to 14 working days in a straightforward case.","Do not pay a seller in full while documents are unresolved; [concierge purchases](/services/concierge) hold funds against milestones for exactly this."]},{"type":"heading","text":"Red flags"},{"type":"checklist","items":["Photocopies offered “because the original is with a brother”.","A duty document whose reference does not appear in any register.","Urgency: a genuine paper does not become more urgent because you asked to see it."]}]', 'documents', 'Chinelo U. leads documentation at HonestCars, handling customs verification, registration and permits across Rivers State.', 'Customs papers, explained without the jargon', 'Duty paid, duty sighted, customs verified, registration complete — what each term really means, and the VIN check that decides whether you can register the car.'),
  ('ph-fuel-cost-by-model', 'What 100km really costs in PH traffic, by model', 'market_intel', 'We tracked real consumption on Camry, Corolla, CR-V, RX 350 and Hilux over the same Aba Road run.', '/img/seed/og-default.svg', 'Fuel economy comparison chart for Port Harcourt cars', 'Ada George', 'Market Analyst', 5, 'published', '2026-09-12 00:00:00', 0, '["Toyota","Honda"]', '[{"type":"paragraph","text":"We tracked real consumption on the same Port Harcourt run for a week: GRA to Trans-Amadi and back, with the Aba Road stretch at peak. Here are the numbers owners reported, plus what they mean per year. The models below are the ones that move through [our listings](/cars) fastest, so the maths sticks."},{"type":"table","head":["Model","Observed","Per 100 km","Yearly (15,000 km)"],"rows":[["Corolla 1.8","11.5 km/l","8.7 L","≈ ₦405,000"],["Camry 2.5","9.8 km/l","10.2 L","≈ ₦475,000"],["CR-V 2.4","8.4 km/l","11.9 L","≈ ₦555,000"],["RX 350 3.5","6.6 km/l","15.2 L","≈ ₦705,000"],["Hilux 2.8 TD","10.4 km/l","9.6 L","≈ ₦445,000 (diesel)"]]},{"type":"callout","tone":"navy","title":"Read the yearly column, not the monthly one","text":"A ₦150,000 yearly fuel difference is easy to ignore in a test drive and impossible to ignore by month five. It is also the reason the V6 you love is usually cheaper to buy than to own."},{"type":"heading","text":"What moves the number most"},{"type":"checklist","items":["Tyre pressure: under-inflated tyres cost more than any driving style change.","Cold-start trips: short school runs in traffic are the worst case for consumption.","AC: it is not free, but in Port Harcourt it is not optional either.","Fuel quality: the cheaper pump is not always the cheaper tank."]},{"type":"paragraph","text":"If you are choosing between two cars and the ₦150,000 a year matters, ask for a [running-cost research brief](/services/research) — we model fuel, tyres, servicing and the model-specific repair bills before you commit, and it is credited against the car if you buy through us."},{"type":"paragraph","text":"Every car we list carries its [full service price list](/services) so you can price the care as well as the car."}]', 'research', 'Ada George runs market intelligence at HonestCars, including the fuel and running-cost data behind our TCO reports.', 'What 100km really costs in PH traffic, by model', 'Observed consumption for Corolla, Camry, CR-V, RX 350 and Hilux on the same Port Harcourt run, converted into what a year of driving actually costs.'),
  ('tyres-you-should-walk-away-from', 'Three tyre conditions that should end your inspection', 'honest_buyers_guide', 'Uneven wear tells you more about a car than the dealer ever will. What to look for and what it costs to fix.', '/img/seed/og-default.svg', 'Tyres and tread depth check on a used car', 'Raph Nicks', 'Head of Inspections', 4, 'published', '2026-09-08 00:00:00', 0, '["Toyota"]', '[{"type":"paragraph","text":"Tyres tell you what the service history will not: how the car was driven, whether the owner noticed problems, and how much they were willing to spend on maintenance. It is one of the first things checked in a [HonestCars inspection](/services/inspection), along with the wheel bearings and alignment."},{"type":"heading","text":"Three conditions that should end the inspection"},{"type":"checklist","items":["Uneven wear across one tyre — alignment or suspension geometry is wrong, and the cause costs more than the tyre.","Different brands on the same axle — the owner was solving problems one wheel at a time.","Cracking on sidewalls with plenty of tread left — a six-year-old tyre is finished regardless of the tread depth. Cars whose tyres and suspension have already been checked carry the HonestCars-Certified badge in [the listings](/cars)."]},{"type":"callout","tone":"amber","title":"The cheap tell","text":"Four new matched tyres on a car that is otherwise average usually means the seller was preparing it to be driven away, which is a good sign. Cheap part-worn tyres on a car with premium trim usually means the opposite."},{"type":"heading","text":"What replacement actually costs in PH"},{"type":"table","head":["Size class","Set of four","Notes"],"rows":[["15–16\\" economy (Corolla, Elantra)","₦180,000–₦280,000","Widely available; price varies by brand"],["17–18\\" mid (Camry, CR-V)","₦320,000–₦520,000","Check dates; old stock is common"],["19\\" + (RX, Prado)","₦650,000+","Budget for it before you buy the car"]]},{"type":"heading","text":"Do this before you agree a price"},{"type":"paragraph","text":"Walk the four corners yourself, or let a [field inspection](/services/inspection) do it before you travel. If the tyres fail any of the three checks above, put the replacement cost on the negotiating table that day — it is the one repair every seller understands and cannot argue with."}]', 'inspection', 'Raph Nicks leads HonestCars inspections, where tyre condition is the fastest read on how a car has been maintained.', 'Three tyre conditions that should end your inspection', 'Uneven wear, mismatched brands and cracked sidewalls: what each one tells you about the owner, and what replacement really costs in Port Harcourt.');
INSERT INTO homepage_modules (`key`, title, payload, is_active, position) VALUES
  ('hero', 'Homepage hero', JSON_OBJECT('headline', NULL, 'subhead', NULL), 0, 10),
  ('announcement', 'Marketing banner', JSON_OBJECT(
INSERT INTO faqs (`scope`, `question`, `answer`, `position`, `is_active`) VALUES
  ('global', 'What do the three verification grades mean?', 'Network-Listed means the dealer gave us the data but we have not seen the car. Field-Checked means an inspector physically stood next to it and photographed it. HonestCars-Certified means it passed our full checklist — OBD2 scan, documents sighted, road test and an honest condition note you can read on the listing.', 1, 1),
  ('global', 'Do I pay the seller directly?', 'No. All payments for a car we are handling go through HonestCars-protected channels. If someone asks you to pay a seller or a "third party" directly, it is not us — stop and message our WhatsApp.', 2, 1),
  ('global', 'Can I bring my own mechanic?', 'Yes, always. We would rather you did. We only ask that you book the viewing so the dealer opens the car for you and nothing is hidden between visits.', 3, 1),
  ('facet:suv-under-15m', 'Are these SUVs really under ₦15m?', 'Every car on this page is listed below ₦15,000,000. Prices move — we refresh the page as dealers update stock, and we will tell you if a price changes before you travel.', 1, 1),
  ('facet:suv-under-15m', 'Will an older SUV cost me more in fuel and parts?', 'Usually yes on fuel, and it depends on the model for parts. The Camry and Corolla platforms are the cheapest to keep on the road in PH; among SUVs, older RAV4 and CR-V models have the best parts availability.', 2, 1),
  ('facet:toyota', 'Why are there so many Toyotas on HonestCars?', 'Because Port Harcourt buys them — parts are everywhere, mechanics know them, and resale value holds. We list whatever is genuinely good stock, and Toyota tends to pass our checklist more often.', 1, 1),
  ('facet:toyota', 'Tokunbo or Nigerian-used Toyota?', 'Both, and we label each one. A Nigerian-used car with a verifiable service history can be better value than a low-grade import. Ask us and we will give you the honest comparison on the specific cars you are looking at.', 2, 1),
  ('service:inspection', 'How long does the inspection take?', 'An hour to an hour and a half on site, then the written report and photos land in your WhatsApp within 4 hours of the check.', 1, 1),
  ('service:inspection', 'Do you inspect cars I found somewhere else?', 'Yes — that is most of our work. Send us the dealer or the location; you do not have to bring the car to us.', 2, 1),
  ('service:inspection', 'What if the car fails the inspection?', 'You get the report either way. If we find something that kills the deal, we say so, and the fee still covers the work we did.', 3, 1),
  ('service:inspection', 'Can I be there for the inspection?', 'You can, and many buyers are. It is also fine to stay away and let the report do the talking.', 4, 1),
  ('service:inspection', 'Is the engine opened during inspection?', 'No. We do not dismantle engines or gearboxes. We scan, test-drive, sight documents and read the body — engine opening is a workshop job we will point you to if it is needed.', 5, 1),
  ('service:concierge', 'What do I get for the retainer?', 'A brief-writing session on WhatsApp, three verified options inside 48–72 hours, and the retainer credited against the success fee when you buy through us.', 1, 1),
  ('service:concierge', 'What if you find nothing that meets my brief?', 'You get the retainer back. The brief is written down so we both know what “nothing” means.', 2, 1),
  ('service:concierge', 'Do I have to buy one of the three cars?', 'No. The options are for you to choose from, walk away from, or compare against something you already found.', 3, 1),
  ('service:concierge', 'Who pays the dealer?', 'HonestCars does, through protected channels. You never pay a seller directly for a car we are handling.', 4, 1),
  ('service:concierge', 'Can you find a specific trim or colour?', 'Usually. Rare trims take longer than 72 hours — we will tell you honestly at the brief stage rather than at the deadline.', 5, 1),
  ('service:documents', 'What documents can you handle?', 'Customs verification, registration, licence renewal, plate numbers, tinted-glass permits, insurance and change of ownership.', 1, 1),
  ('service:documents', 'How do I know my papers are genuine?', 'We sight them at the source: customs portal, licensing office, or the issuing underwriter. You get photos of what we verified and what we could not.', 2, 1),
  ('service:documents', 'Can you renew a licence for someone else?', 'Yes, with signed authority and a copy of the holder’s ID. We will list exactly what to send before you pay anything.', 3, 1),
  ('service:documents', 'How long does registration take?', 'Routine registration is 3–7 working days; customs verification depends on the terminal queue. We give you a realistic date, not a hopeful one.', 4, 1),
  ('service:documents', 'Do you collect the car or do I bring it?', 'Both are possible across Port Harcourt. Some paperwork needs the vehicle physically present; we tell you up front.', 5, 1),
  ('service:tracking', 'Which tracker brands do you install?', 'We fit the bundles listed on this page and support the platform that comes with them. If you already own a device, we can advise before you buy another.', 1, 1),
  ('service:tracking', 'How long does installation take?', 'Standard and Premium installs are 60–90 minutes at a partner bay or a location you choose. Fleet installs are scheduled as a batch.', 2, 1),
  ('service:tracking', 'What happens if the device stops reporting?', 'Message us. A device that has gone quiet is a support case, not a wait-and-see — that is the point of paying for a monitored bundle.', 3, 1),
  ('service:tracking', 'Do I have to keep paying every year?', 'The platform subscription renews yearly. We send a reminder 30 days out and you can renew by transfer, card or on this site.', 4, 1),
  ('service:tracking', 'Can you track a car I am buying before I complete payment?', 'Not before handover. We can, however, fit the tracker as part of a protected purchase so it is live the day you take the keys.', 5, 1),
  ('service:research', 'What is in a TCO report?', 'A five-year cost estimate for the specific car: fuel at PH prices, service intervals, common failure points for that model and year, insurance band and expected resale.', 1, 1),
  ('service:research', 'Can you check a price before I travel to see a car?', 'Yes — that is the fastest thing we do. Send the link and the asking price; you get a market position and the reasons behind it.', 2, 1),
  ('service:research', 'Do you use real Port Harcourt data?', 'Our own deals, our dealers’ transactions and live network pricing — not a scrape of foreign listings converted at the wrong rate.', 3, 1),
  ('service:research', 'How is it delivered?', 'A written PDF in your account and a WhatsApp summary. Reports go out inside 48–72 hours of the brief being confirmed.', 4, 1),
  ('service:consultation', 'What happens in the 30 minutes?', 'You bring your shortlist and your budget; we go through them one by one and you leave with a ranked list and a price ceiling.', 1, 1),
  ('service:consultation', 'Can I record the call?', 'Yes. We send a written summary afterwards either way.', 2, 1),
  ('service:consultation', 'What if I have no shortlist yet?', 'Come anyway. Half of these calls end with “do not buy any of these three”, which is the cheapest advice you will get.', 3, 1),
  ('service:consultation', 'Do you sell me a car on the call?', 'No. The consultation is advice, not a sales call — if a car on our network fits, you will still be told the faults first.', 4, 1),
  ('service:parts', 'How do you match the part?', 'By VIN and engine code, not by “the same model”. Send the VIN or the chassis number and we confirm the match before quoting.', 1, 1),
  ('service:parts', 'How does escrow-protected payment work?', 'You pay a milestone amount into the protected flow; the supplier is paid when the part is delivered and verified. No full upfront payment to a stranger.', 2, 1),
  ('service:parts', 'What if the part is wrong?', 'If we supplied the wrong match, we fix it. If the part number came from you, we will help you return it but the supplier’s terms apply — we say this before you pay.', 3, 1),
  ('service:parts', 'Do you fit parts too?', 'We do not run a workshop. We can point you to mechanics in PH who work on your model, and we can send an inspector to confirm the fitting on request.', 4, 1),
  ('service:sell-swap', 'How fast is the valuation?', 'Within 24 hours from live network data. If you want the certified listing, we book an inspection first — that is what pushes the price up.', 1, 1);
INSERT INTO faqs (`scope`, `question`, `answer`, `position`, `is_active`) VALUES
  ('service:sell-swap', 'What does it cost to sell?', 'Nothing up front. We agree a success commission before the car is listed; if it does not sell, you owe nothing.', 2, 1),
  ('service:sell-swap', 'Can I swap instead of selling?', 'Yes. The swap brief reuses the concierge flow: we value yours, then bring verified options and net off the difference.', 3, 1),
  ('service:sell-swap', 'Will you list my car on other sites?', 'We list it on HonestCars with its real condition note. If you also want it on other platforms, that is your call and we will tell you how to describe it honestly.', 4, 1),
  ('service:dealer-services', 'What is in the media package?', 'A shot list per car — front three-quarter, sides, interior, dash, odometer, engine bay and any faults — uploaded to your listing with descriptions written for buyers.', 1, 1),
  ('service:dealer-services', 'How does lead protection work?', 'Buyer contact details stay with HonestCars until you accept a viewing; we route the buyer to you when it is real, not when it is curious.', 2, 1),
  ('service:dealer-services', 'Is there a minimum number of cars?', 'No, but per-car pricing improves from five cars a month. Talk to us about the lot as a whole.', 3, 1),
  ('service:dealer-services', 'Do you take a commission on cars I sell?', 'Not on your own walk-in sales. Featured placement and services are a fee; cars that come through HonestCars-protected purchases carry the agreed commission.', 4, 1),
  ('page:hire', 'Is fuel included?', 'No. The vehicle comes with a full tank and returns full, or we charge the difference at pump price.', 1, 1),
  ('page:hire', 'Do you deliver and pick up?', 'Yes, within Port Harcourt. Airport pickup at Omagwa is available on every class.', 2, 1),
  ('page:hire', 'What documents do I need?', 'A valid licence, a second ID for the file, and a refundable caution deposit. Corporate accounts sign a simple agreement instead.', 3, 1),
  ('page:hire', 'Can I take the car out of Rivers State?', 'With written approval before the trip — it changes the insurance cover. Ask us and we will arrange it.', 4, 1),
  ('page:verification', 'Who inspects the cars?', 'HonestCars inspectors, paid by HonestCars. Not the dealer, not a freelance agent who also works for the lot.', 1, 1),
  ('page:verification', 'Can a grade change?', 'Yes, in both directions. A car can be re-inspected and re-graded if it is repaired, damaged or simply older than the last report.', 2, 1),
  ('page:verification', 'What does the honest note actually contain?', 'What we found: paint work, leaks, codes, tyre life, panel gaps, electrical faults and anything that made us hesitate. It is written to be read by a buyer, not a workshop.', 3, 1),
  ('page:verification', 'Can I see the photos of a known fault?', 'Every fault we record is photographed where it can be. If something is invisible in a photo, the note explains how to check it yourself.', 4, 1),
  ('page:verification', 'Do inspectors take money from sellers?', 'No. It is a dismissable offence and we audit it. If a dealer ever offers an inspector anything, tell us and we will show you the outcome.', 5, 1),
  ('page:how-it-works', 'How much of this is free?', 'Browsing, comparing and asking questions are free. Inspections, documents, tracking, research and the concierge retainer are paid services, priced on each page.', 1, 1),
  ('page:how-it-works', 'What if a car sells while I am deciding?', 'It happens — PH moves fast. We will offer the next closest match, and the concierge keeps your brief on file.', 2, 1),
  ('page:how-it-works', 'Can I skip the inspection and just buy?', 'Yes, but we will say plainly that you are buying on the dealer’s word. For network-listed cars that is exactly what the grade means.', 3, 1),
  ('page:how-it-works', 'Do I need an account?', 'No. Enquiries, booking and guest checkout all work without one. An account just keeps your requests, orders and saved cars in one place.', 4, 1),
  ('page:about', 'Where are you based?', 'Port Harcourt, Rivers State. We operate virtually — inspections come to the car, wherever it is in PH.', 1, 1),
  ('page:about', 'How do you make money?', 'Service fees, the shop, hire, and a success commission on cars bought through protected purchases. We do not charge buyers to look.', 2, 1),
  ('page:about', 'Is Honest Cars LTD a registered company?', 'Yes. The CAC registration is shown in the footer and on every receipt.', 3, 1),
  ('page:about', 'Do you buy cars yourself?', 'No. We are not a dealer and we do not hold stock — our incentive is to tell you the truth about someone else’s car, then help you buy it well.', 4, 1),
  ('page:partner', 'What does it cost a dealer?', 'There is no listing fee. You pay for the services you use — photography, featured placement, intelligence — and commission on protected sales.', 1, 1),
  ('page:partner', 'Do you hide the buyer from me?', 'Until you accept a viewing, yes. After that you get the buyer’s name and number, and we stay in the middle for documents and payment.', 2, 1),
  ('page:partner', 'Can I keep selling on other platforms?', 'Yes. Non-exclusive is the default. We only ask that you tell us when a car goes under offer elsewhere so we stop sending buyers.', 3, 1),
  ('page:partner', 'How do you verify a lot before it joins?', 'We visit, sight the CAC papers and a utility bill, check two references from previous customers, and agree the honesty rules in writing.', 4, 1),
  ('page:contact', 'What is the fastest way to reach you?', 'WhatsApp. It is answered by the ops team in Port Harcourt, not a bot, and it is the same number on every page.', 1, 1),
  ('page:contact', 'Can I come to an office?', 'We do not run a walk-in office — inspections come to you and meetings happen where the car is. Say the word and we will arrange a meet-point.', 2, 1),
  ('page:contact', 'How long until someone replies?', 'Within working hours, minutes on WhatsApp. Anything sent after 6pm is answered the next morning.', 3, 1),
  ('page:contact', 'How do I report a seller who asked for a direct payment?', 'Message us on WhatsApp immediately with the car reference. We investigate, and if a partner dealer is involved, their agreement with us is reviewed.', 4, 1),
  ('page:shop', 'Is checkout secure?', 'Payment runs through Paystack or Flutterwave inline checkout. We never see or store your card details.', 1, 1),
  ('page:shop', 'Can I pay on delivery?', 'Within Port Harcourt, yes on some items — the checkout will show it. Trackers with installation are paid before the install slot is confirmed.', 2, 1),
  ('page:shop', 'What is the warranty on trackers?', '12 months on the device, 24 months on the Premium unit, with the platform subscription renewed yearly.', 3, 1),
  ('page:shop', 'Do you deliver outside Port Harcourt?', 'We courier small items nationwide and list river towns separately at checkout. Installation is Port Harcourt only.', 4, 1),
  ('shop:trackers', 'Will you install it in my car at my house?', 'Yes, within Port Harcourt, by appointment. Pick the install add-on and we will call you to fix a slot.', 1, 1),
  ('shop:trackers', 'Does the tracker need a SIM card subscription?', 'The device needs a data SIM and a platform subscription; the first year is included in the price shown.', 2, 1),
  ('shop:trackers', 'Can a thief remove it?', 'A determined thief can remove anything; the point is time and noise. Premium includes a second device hidden elsewhere, which is why we recommend it for 2020-up models.', 3, 1),
  ('shop:diagnostics', 'Will the scanner work on my car?', 'The models we sell cover OBD2-compliant vehicles from 2004 onward. Pre-2004 and some older diesels need the manufacturer tool — message us your car first.', 1, 1);
INSERT INTO faqs (`scope`, `question`, `answer`, `position`, `is_active`) VALUES
  ('shop:diagnostics', 'Does it clear airbag lights?', 'It reads and clears standard engine codes. Airbag and ABS modules depend on the model; the page lists what each unit supports.', 2, 1),
  ('shop:care_kits', 'Is the care kit worth it if I have a new car?', 'The basic kit is for anyone doing PH roads. Add the roadside kit if you drive at night or out of town.', 1, 1),
  ('shop:care_kits', 'Can I buy just one item from a kit?', 'Message us on WhatsApp — we can usually split a kit and adjust the price.', 2, 1);
